KINDS=[("identity","evidence","validation"),("definition","authority","interoperability"),("relationship","temporal","access"),("requirement","decision","exception"),("ownership","provenance","privacy"),("classification","quality","security"),("composition","measurement","validation"),("state","lifecycle","retention")]

def make_finding(raw,index):
    fid,name,description,refs,value_kind,required=raw; kinds=KINDS[index%len(KINDS)]
    return {"id":fid,"name":name,"description":description,"source_refs":refs,"questions":[
        {"id":fid+"-q01","text":f"What identity, class, role, scope, version and values define {name.lower()}?","kind":kinds[0],"answer_data":["identifiers","classes and roles","versions and scope","values and unknowns"]},
        {"id":fid+"-q02","text":f"Which issuer authority, source, evidence, method and event or effective time support {name.lower()}?","kind":kinds[1],"answer_data":["authority","source and evidence","method and profile","event and effective time","confidence"]},
        {"id":fid+"-q03","text":f"How is {name.lower()} validated, disclosed, contested, corrected, superseded and retained without changing issued history?","kind":kinds[2],"answer_data":["validation","access and disclosure","contest and correction","lineage","retention"]}],
        "data_elements":[{"id":fid+"-data","name":name+" data","description":"Structured attestation and credential data for "+name.lower()+".","value_kind":value_kind,"cardinality":"1" if required else "0..n","required":required,"source_refs":refs}],
        "artifacts":[{"id":fid+"-record","name":name+" record","description":"Versioned evidence-bearing record for "+name.lower()+" with credential binding, authority, time, provenance and disclosure marking.","media_or_form":["logical attestation assertion","credential, evidence, event or validation reference"],"serial":True,"identity_strategy":"Credential or attestation identifier plus "+fid+" assertion, artifact or event identifier; subject name, serial, timestamp and digest never identify the credential alone.","source_refs":refs}],"inline_only_rationale":None}

def structure():
    cursor=0; bundles=[]
    for bid,name,description,rationale,refs,layers in BUNDLES:
        made_layers=[]
        for lid,lname,ldescription,lrefs,findings in layers:
            made=[]
            for raw in findings: made.append(make_finding(raw,cursor)); cursor+=1
            made_layers.append({"id":lid,"name":lname,"description":ldescription,"source_refs":lrefs,"findings":made})
        bundles.append({"id":bid,"name":name,"description":description,"rationale":rationale,"source_refs":refs,"layers":made_layers})
    return {"bundles":bundles}

